#define KELLY_DECOMP_FULL_FEMENU_ENTRY
#define FEMenuEntry FEMenuEntryShared
#define TextString TextStringShared
#include "KS/SRC/ks/FEMenu_shared.h"
#undef FEMenuEntry
#include "KS/SRC/ks/FEPanel_shared.h"
#undef TextString
#include "KS/SRC/ks/GraphicalMenuSystem_shared.h"

class TextString : public TextStringShared
{
public:
	TextString(Font* font, stringx text, float x, float y, int z, float scale,
		Font::HORIZJUST hjust, Font::VERTJUST vjust, color32 color);
};

class FEMenuEntry : public FEMenuEntryShared
{
public:
	FEMenuEntry(char* text, FEMenu* menu);
	void SetFont(Font* font);
};

class FEManager
{
public:
	color32 col_unselected;
	color32 col_highlight;
	color32 col_highlight2;
	color32 col_info_b;
	Font font_hand;
	Font font_bold;
};

extern stringx ksGlobalTextArray[];
enum { GT_FE_MENU_DIFFICULTY };
enum
{
	FEMENU_HAS_COLOR = 0x20,
	FEMENU_HAS_COLOR_HIGH = 0x40,
	FEMENU_HAS_COLOR_HIGH_ALT = 0x80,
	FEMENU_WRAP = 0x100
};

void* operator new(unsigned int);
#define NEW new

class MultiSubMenu : public FEMenu
{
public:
	enum
	{
		SubEasyEntry,
		SubMediumEntry,
		SubHardEntry,
		SubEnd
	};
	GraphicalMenuSystem* sys;
	FEMenuEntry* entry[SubEnd];
	TextString* difficulty;

	static const int spacing = 17;
	int push[SubEnd];
	int time[SubEnd];

public:
	MultiSubMenu(FEMenuSystem* s, int x, int y);
};

MultiSubMenu::MultiSubMenu(FEMenuSystem* s, int x, int y)
{
	cons(s, x, y);
	color = s->manager->col_unselected;
	color_high = s->manager->col_highlight;
	flags |= FEMENU_HAS_COLOR | FEMENU_HAS_COLOR_HIGH | FEMENU_HAS_COLOR_HIGH_ALT | FEMENU_WRAP;
	color_high_alt = s->manager->col_highlight2;
	scale = scale_high = 0.9f; //0.5f;
	sys = (GraphicalMenuSystem*) s;

	entry[SubEasyEntry] = NEW FEMenuEntry("", this);
	entry[SubMediumEntry] = NEW FEMenuEntry("", this);
	entry[SubHardEntry] = NEW FEMenuEntry("", this);

	for(int i=0; i<SubEnd; i++)
	{
		entry[i]->SetPos(x, y+(i-1)*spacing);
		entry[i]->SetFont(&s->manager->font_hand);
		Add(entry[i]);
	}

	float diff_scale = 0.65f;
	difficulty = NEW TextString(&s->manager->font_bold, ksGlobalTextArray[GT_FE_MENU_DIFFICULTY], 479, 233, 0, diff_scale, Font::HORIZJUST_CENTER, Font::VERTJUST_CENTER, s->manager->col_info_b);

	push[SubEasyEntry]		= 2500;
	push[SubMediumEntry]	= 5000;
	push[SubHardEntry]		= 10000;
	time[SubEasyEntry]		= 1000;
	time[SubMediumEntry]	= 10000;
	time[SubHardEntry]		= 30000;

	dy = spacing;
	SetHelpText(0);
}
